Lemma rw_cells_head_recast : forall m A c c' post,
  rw_cells rsegs m A (c :: post) -> cells_wf [c'] -> cbytes c' = cbytes c -> csize c' = csize c ->
  rw_cells rsegs m A (c' :: post).
Proof.
  intros m A c c' post RC WF EB ES.
  apply (proj1 (rw_cells_app _ _ _ [c] post)) in RC. destruct RC as [R1 R2].
  apply (proj2 (rw_cells_app _ _ _ [c'] post)). split.
  - eapply rw_cells_reshape; [exact R1| exact WF| cbn; rewrite EB; reflexivity].
  - cbn [cells_size] in *. rewrite ES. exact R2.
Qed.

(* [comment removed for export] *)
Lemma rw_cells_C4_m1 : forall m A post,
  rw_cells rsegs m A (C4 (Z_to_bv 64 18446744073709551615) :: post) -> rw_cells rsegs m A (C4 (wz 4294967295) :: post).
Proof.
  intros m A post RC. eapply rw_cells_head_recast; [exact RC| cbn; split; [reflexivity| exact I]| | reflexivity].
  cbn [cbytes]. unfold wz. symmetry. exact le4_m1.
Qed.


