Definition fzB1_post (gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (P A : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' j344 j32 j16 j8,
    ms' = MS (mkR (Z_to_bv 64 P_FZ_RET_REG) (Z_to_bv 64 P) gp tp t0 t1 t2 s0 s1
                  (Z_to_bv 64 P) (Z_to_bv 64 (P + 384)) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_ALLOC_OBJ_REGISTRY) fc None m' (seg_rom rsegs)
    /\ munch [(P, P + 8); (P + 384, P + 392); (A, A + 16)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ rw_cells rsegs m' P [C8 (wz A); CB 344 j344]
    /\ rw_cells rsegs m' (P + 352) [CB 32 j32]
    /\ rw_cells rsegs m' (P + 384) [C8 (wz A); CB 16 j16]
    /\ rw_cells rsegs m' A [C8 (wz VP_ALLOCIMPL); CB 8 j8].

