    (F : bvmap 5 word) fc (m : mem) (P A : Z) (j408 jA : list byte),
  rw_cells rsegs m P [CB 408 j408] ->
  hceil <= P -> P + 512 < 2^64 ->
  rw_cells rsegs m A [CB 16 jA] -> 0 < A -> A + 16 <= hceil ->
  mem_inv rsegs m ->
  evt rsegs (fzB1_post gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc P A m)
