(* [comment removed for export] *)
Definition fzB3_post (gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (P R : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' j351,
    ms' = MS (mkR (Z_to_bv 64 P_FZ_RET_SCH) (Z_to_bv 64 P) gp tp t0 t1 t2 s0 s1
                  (Z_to_bv 64 R) (Z_to_bv 64 P) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_MAKE_SVC_SCHED) fc None m' (seg_rom rsegs)
    /\ munch [(P, P + 1)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ rw_cells rsegs m' P [CB 1 [b8 0]; CB 351 j351].

Lemma fzB3 : forall gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P allocb R : Z) (cP : list cell) (j8 : list byte),
  rw_cells rsegs m P cP -> cells_size cP = 352%nat -> rw_cells rsegs m (P + 384) [C8 (wz allocb); C8 (wz R); CB 8 j8] ->
